head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst00800";
scwin.loadYn = false;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst00800.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "callPapagoTranslator");
    scwin.swapOptions('#language', '#targetLanguage');
    scwin.swapOptions('#targetLanguage', '#language');
    (($c.util.getComponent('slc_target')) && ($c.util.getComponent('slc_target')).setDisabled ? ($c.util.getComponent('slc_target')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    (($c.util.getComponent('slc_source')) && ($c.util.getComponent('slc_source')).setDisabled ? ($c.util.getComponent('slc_source')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.init();
        $("#txa_text").on("propertychange change keyup paste input focus", function() {
                if (!scwin.loadYn) {
                    $c.util.getComponent('txa_text').setValue("");
                    scwin.loadYn = true;
                }
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst00800.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst00800.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name img_32_onclick
 * @description 「선택」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_32_onclick = async function(e){
    try {
        await scwin.fnSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst00800.img_32_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearch_onclick
 * @description btn_fnSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearch_onclick = async function(e){
    try {
        await scwin.fnSearch(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst00800.btn_fnSearch_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/common/krxPapagoTranslator.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    if (await scwin.checkLength()) {
        (($c.util.getComponent('slc_target')) && ($c.util.getComponent('slc_target')).setDisabled ? ($c.util.getComponent('slc_target')).setDisabled((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
        (($c.util.getComponent('slc_source')) && ($c.util.getComponent('slc_source')).setDisabled ? ($c.util.getComponent('slc_source')).setDisabled((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
        $c.util.getComponent('slc_target').setValue("en");
        $c.util.getComponent('slc_source').setValue("ko");
        scwin.dial();
        await scwin.tx_fnSearch_ajaxsubmit();
    }
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCallBack = async function (data) {
    (($c.util.getComponent('slc_target')) && ($c.util.getComponent('slc_target')).setDisabled ? ($c.util.getComponent('slc_target')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    (($c.util.getComponent('slc_source')) && ($c.util.getComponent('slc_source')).setDisabled ? ($c.util.getComponent('slc_source')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    try {
        if (scwin.isHTML(data)) {
            await $c.win.alert("현재 해당 서비스를 이용할 수 없습니다. 시스템 관리자에게 문의 바랍니다.");
            document.write(data);
            document.close();
        } else {
            const resultJson = (typeof data === "string" ? JSON.parse(data) : data);
            const transrationText = resultJson.dataList[0].response.translatedText;
            $c.util.getComponent('txa_afterText').setValue(transrationText);
        }
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jlddst00800' });
        await $c.win.alert("지금 사용하고 계신 단어로는 사이트 이용이 불가능합니다.");
        $c.win.setPageFrameSrc($c.win.getFrame(), null);
    }
};

/**
 * @method
 * @name dial
 * @description dial 처리
 * @returns {void}
 * @hidden N
 */
scwin.dial = function () {
    ($.fn && $.fn.dialog ? $("#dialogLoading").dialog({ title: 'Translation is in progress.', height: 100, closeOnEscape: false, draggable: false, resizable: false, modal: true }) : undefined);
    $("#dialogLoading").attr("title", "Translation is in progress.");
    /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
    $(".ui-widget-overlay").css("background-image", "none");
};

/**
 * @method
 * @name isHTML
 * @description is HTML 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.isHTML = function (str) {
    const pattern = /<([A-Za-z][A-Za-z0-9]*)\b[^>]*>(.*?)<\/\1>/;
    return pattern.test(str);
};

/**
 * @method
 * @name swapOptions
 * @description swap Options 처리
 * @param {*} selector1 selector1
 * @param {*} selector2 selector2
 * @returns {void}
 * @hidden N
 */
scwin.swapOptions = function (selector1, selector2) {
    $(selector1).change(function() {
            const selectedOption = $(selector1).val() === 'ko' ? 'en' : 'ko';
            $(selector2).val(selectedOption);
    });
};

/**
 * @method
 * @name swapValues
 * @description swap Values 처리
 * @param {*} id1 id1
 * @param {*} id2 id2
 * @returns {void}
 * @hidden N
 */
scwin.swapValues = function (id1, id2) {
    const temp = $(id1).val();
    $(id1).val($(id2).val());
    $(id2).val(temp);
};

/**
 * @method
 * @name btnSwapValues
 * @description btn Swap Values 처리
 * @returns {void}
 * @hidden N
 */
scwin.btnSwapValues = function () {
    scwin.swapValues('#source', '#target');
    scwin.swapValues('#text', '#afterText');
};

/**
 * @method
 * @name changeSwapComboBox
 * @description change Swap Combo Box 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeSwapComboBox = function () {
    $('select').change(function() {
            const otherSelectBox = $(this).attr('id') === 'source' ? '#target' : '#source';
            if ($(this).val() === $(otherSelectBox).val()) {
                $(otherSelectBox).val($(this).val() === 'ko' ? 'en' : 'ko');
            }
    });
};

/**
 * @method
 * @name checkLength
 * @description check Length 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkLength = async function () {
    const limit = 4500;
    const textValue = $c.util.getComponent('txa_text').getValue();
    const trimmedValue = textValue.trim();
    const length = trimmedValue.length;
    if (length === 0) {
        await $c.win.alert("번역할 문자를 넣어주세요.");
        return false;
    } else {
        if (length > limit) {
            await $c.win.alert("입력 가능한 글자는 " + limit + "자를 넘을 수 없습니다.");
            return false;
        }
    }
    return true;
};
